export type AuditAction = "user_suspended" | "account_deleted";

export interface AuditEntry {
  action: AuditAction;
  actorId: string;
  targetId: string;
  metadata: Record<string, string>;
}

base.src/modules/audit/audit.ts:
import type { Database } from "../../db";
import type { AuditEntry } from "./audit.types";

export async function writeAudit(tx: Database, entry: AuditEntry): Promise<void> {
  await tx.query(
    "INSERT INTO audit_log (action, actor_id, target_id, metadata) VALUES ($1, $2, $3, $4)",
    [entry.action, entry.actorId, entry.targetId, JSON.stringify(entry.metadata)],
  );
}

