import { db } from "../../db";
import { writeAudit } from "../audit/audit";

export async function deleteAccount(actorId: string, userId: string): Promise<void> {
  await db.transaction(async (tx) => {
    await tx.query("UPDATE users SET status = 'deleted' WHERE id = $1", [userId]);
    await tx.query("DELETE FROM sessions WHERE user_id = $1", [userId]);
    await writeAudit(tx, {
      action: "account_deleted",
      actorId,
      targetId: userId,
      metadata: { reason: "admin_request" },
    });
  });
}
